class Solution {
public:
    int countMagicalPairs(string s) {
        int n = s.size();
        vector<vector<int>> right(n, vector<int>(27, 0));
        for (int start = 0; start < n; start++) {
            int mask = 0;
            for (int end = start; end < n; end++) {
                mask |= (1 << (s[end] - 'a'));
                int d = __builtin_popcount(mask);
                right[start][d]++;
            }
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            int mask = 0;
            for (int j = i; j < n - 1; j++) {
                mask |= (1 << (s[j] - 'a'));
                int d = __builtin_popcount(mask);
                ans += right[j + 1][d];
            }
        }
        return (int)ans;
    }
};
